// Original public-register common-history fixtures; no chip arithmetic or hardware I/O.
package main
import("crypto/sha256";"encoding/json";"flag";"fmt";"os";"path/filepath")
type operation struct{Kind string `json:"kind"`;Reg int `json:"reg"`;Value int `json:"value"`;Count int `json:"count"`}
type fixture struct{Name string `json:"name"`;N int `json:"contributors"`;Middle int `json:"middle_tl"`;Init string `json:"init"`;Model string `json:"model_init"`;Event string `json:"event"`;Hashes map[string]string `json:"hashes"`;InitOps []operation `json:"init_operations"`;ModelOps []operation `json:"model_init_operations"`;EventOps []operation `json:"event_operations"`;NativeFrames int `json:"native_frames"`;Stride int `json:"stride"`;Keys []int `json:"manual_masks"`;EventBytes int `json:"event_bytes"`}
func main(){output:=flag.String("output","","new artifact directory");flag.Parse();if *output==""||flag.NArg()!=0{fmt.Fprintln(os.Stderr,"use -output NEW_DIRECTORY");os.Exit(1)};e:=generate(*output);if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func generate(output string)error{e:=os.Mkdir(output,0755);if e!=nil{return e};cases:=[]fixture{};for _,spec:=range[][2]int{{32,0},{32,32},{1,0},{1,32},{32,40},{1,40}}{n,mid:=spec[0],spec[1];c:=fixture{Name:fmt.Sprintf("held-n%02d-tl32-%02d-32",n,mid),N:n,Middle:mid,NativeFrames:16384,Stride:1,Keys:make([]int,8),Hashes:map[string]string{}};for ch:=0;ch<8;ch++{if n==32{c.Keys[ch]=120}else if ch==0{c.Keys[ch]=8}};init:=[]operation{wr(20,48),wr(15,0),wr(1,0),wr(16,0),wr(17,0),wr(18,0),wr(24,0),wr(25,0),wr(25,128),wr(27,0)};for ch:=0;ch<8;ch++{init=append(init,wr(8,ch))};for r:=32;r<256;r++{v:=0;switch{case r<40:v=199;case r<48:v=74;case r>=96&&r<128:v=127;if n==32||r==96{v=32};case r>=128&&r<160:v=31;case r>=224:v=15};init=append(init,wr(r,v))};for ch:=0;ch<8;ch++{init=append(init,wr(8,c.Keys[ch]|ch))};event:=[]operation{wait(4096)};for stage,level:=range[]int{mid,32}{for ch:=0;ch<8;ch++{event=append(event,wr(32+ch,135))};event=append(event,wait(1024));for r:=96;r<128;r++{v:=127;if n==32||r==96{v=level};event=append(event,wr(r,v))};event=append(event,wait(1024));for ch:=0;ch<8;ch++{event=append(event,wr(32+ch,199))};if stage==0{event=append(event,wait(4096))}};model:=append(cleanup(),wait(55938));model=append(model,init...);model=append(model,wait(8192));c.InitOps=init;c.ModelOps=model;c.EventOps=event;c.Init=c.Name+"-init.bin";c.Model=c.Name+"-model-init.bin";c.Event=c.Name+"-event.bin";for _,item:=range[]struct{name string;ops []operation}{{c.Init,init},{c.Model,model},{c.Event,event}}{data:=encode(item.ops);if len(data)>8192{return fmt.Errorf("program too large")};if item.name==c.Event{c.EventBytes=len(data);if len(data)!=307{return fmt.Errorf("EVENT bytes")}};c.Hashes[item.name]=hash(data);e=write_file(filepath.Join(output,item.name),data);if e!=nil{return e}};cases=append(cases,c)};raw,e:=json.MarshalIndent(map[string]interface{}{"state":"proposal_only_no_execution_coverage","method_sha256":"0223bbdbd18bbb9b37812d13191b3a4fa9b7ce3bbf3d0a42de08b1fa28279234","profiles":cases,"future_start":"UNKNOWN_ROOT_ONLY","physical_delay_equivalence":false},"","  ");if e!=nil{return e};e=write_file(filepath.Join(output,"cases.json"),append(raw,'\n'));if e!=nil{return e};return write_file(filepath.Join(output,"cleanup.bin"),encode(cleanup()))}
func wr(r,v int)operation{return operation{Kind:"write",Reg:r,Value:v}}
func wait(n int)operation{return operation{Kind:"delay",Count:n}}
func cleanup()[]operation{v:=[]operation{wr(20,48),wr(15,0)};for r:=224;r<256;r++{v=append(v,wr(r,15))};for ch:=0;ch<8;ch++{v=append(v,wr(8,ch))};return v}
func encode(ops []operation)[]byte{raw:=[]byte{};for _,op:=range ops{if op.Kind=="write"{raw=append(raw,1,byte(op.Reg),byte(op.Value))}else{raw=append(raw,2,byte(op.Count),byte(op.Count>>8))}};return append(raw,0)}
func write_file(path string,data []byte)error{f,e:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return e};_,e=f.Write(data);ce:=f.Close();if e!=nil{return e};return ce}
func hash(data []byte)string{return fmt.Sprintf("%x",sha256.Sum256(data))}
